  const reqUserAvaters = (userIds = []) => {
    return new Promise((resolve, reject) => {
      if (!userIds || userIds.length == 0) {
        formatAppLog("log", "at api/reqUserAvater/index.ts:9", "userIds is null");
        resolve([]);
        return;
      }
      nr.database().collection("uni-id-users").where({
        _id: nr.database().command.in(userIds)
      }).field("_id,avatar_file").get().then((res) => {
        if (res.result.data.length == 0) {
          resolve([]);
          return;
        }
        const urlArr = res.result.data.map((i2) => i2.avatar_file.url);
        Promise.all(urlArr.map((url2) => getUserAvaterFromCloud(url2))).then((res2) => {
          resolve(res2);
        });
      }).catch((err) => {
        reject(err);
      });
    });
  };
  function getUserAvaterFromCloud(avaterUrl) {
    return new Promise((resolve, reject) => {
      if (!avaterUrl) {
        formatAppLog("log", "at api/reqUserAvater/index.ts:38", "avaterUrl为空,不请求cloud了");
        resolve("");
        return;
      }
      if (avaterUrl.length != 0 && avaterUrl.substring(0, 8) == "cloud://") {
        nr.getTempFileURL({
          fileList: [avaterUrl]
        }).then((res) => {
          const avaterFile = res.fileList[0].tempFileURL;
          resolve(avaterFile);
        }).catch((err) => reject(err));
      }
    });
  }
