  let commentsList = [];
  const reqBlogComments = (articleId, pageNo, pageSize) => {
    return new Promise((resolve, reject) => {
      if (articleId == "") {
        formatAppLog("error", "at api/reqBlogComments/index.ts:9", "article_id is null! ");
        reject("article_id is null! ");
        return;
      }
      nr.database().collection("blog-comments").where({ article_id: articleId }).skip((pageNo - 1) * pageSize).limit(pageSize).get({
        getTree: true
      }).then((res) => {
        commentsList.splice(0);
        getCommentsListFromOld(res.result.data);
        resolve({ data: commentsList, "total": res.result.data.length });
      }).catch((err) => reject(err));
    });
  };
  function getCommentsListFromOld(params) {
    params.forEach((item) => {
      const { children } = item;
      item.id = item._id;
      if (children.length != 0) {
        item.children = [];
        commentsList.push(item);
        getCommentsListFromOld(children);
        return;
      }
      commentsList.push(item);
    });
  }
  const addBlogComment = (comment) => {
    return new Promise((resolve, reject) => {
      nr.database().collection("blog-comments").add(comment).then((res) => resolve(res)).catch((err) => reject(err));
    });
  };
  const deleteCommentsByIds = (ids) => {
    return new Promise((resolve, reject) => {
      nr.database().collection("blog-comments").where({
        _id: nr.database().command.in(ids)
      }).remove().then((res) => resolve(res)).catch((err) => reject(err));
    });
  };
  const clickedLike = (id, like_count) => {
    nr.database().command;
    return new Promise((resolve, reject) => {
      let update = { like_count };
      nr.database().collection("blog-comments").where({ _id: id }).update(update).then((res) => resolve(res)).catch((err) => reject(err));
    });
  };
